    14  static sf_count_t vfget_filelen (void *user_data)
    15  {
    16    VIO_DATA *vf = (VIO_DATA *)user_data;
    17    return vf->length;
    18  }
    19
    20  static sf_count_t vfseek (sf_count_t offset, int whence, void *user_data)
    21  {
    22    VIO_DATA *vf = (VIO_DATA *)user_data;
    23
    24    switch (whence)
    25    {
    26      case SEEK_SET:
    27        vf->offset = offset;
    28        break ;
    29
    30      case SEEK_CUR:
    31        vf->offset = vf->offset + offset;
    32        break ;
    33
    34      case SEEK_END:
    35        vf->offset = vf->length + offset;
    36        break;
    37
    38      default:
    39        break;
    40    }
    41
    42    return vf->offset;
    43  }
    44
    45  static sf_count_t vfread (void *ptr, sf_count_t count, void *user_data)
    46  {
    47    VIO_DATA *vf = (VIO_DATA *)user_data;
    48
    49    if (vf->offset + count > vf->length)
    50    {
    51      count = vf->length - vf->offset;
    52    }
    53
    54    memcpy(ptr, vf->data + vf->offset, count);
    55    vf->offset += count;
    56
    57    return count;
    58  }
    59
    60  static sf_count_t vfwrite (const void *ptr, sf_count_t count, void *user_data)
    61  {
    62    (void)ptr;
    63    (void)count;
    64    (void)user_data;
    65
    66    // Cannot write to this virtual file.
    67    return 0;
    68  }
    69
    70  static sf_count_t vftell (void *user_data)
    71  { VIO_DATA *vf = (VIO_DATA *)user_data;
    72
    73    return vf->offset;
    74  }
