    76  extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
    77  {
    78    VIO_DATA vio_data;
    79    SF_VIRTUAL_IO vio;
    80    SF_INFO sndfile_info;
    81    SNDFILE *sndfile = NULL;
    82    float* read_buffer = NULL;
    83
    84    // Initialize the virtual IO structure.
    85    vio.get_filelen = vfget_filelen;
    86    vio.seek = vfseek;
    87    vio.read = vfread;
    88    vio.write = vfwrite;
    89    vio.tell = vftell;
    90
    91    // Initialize the VIO user data.
    92    vio_data.data = data;
    93    vio_data.length = size;
    94    vio_data.offset = 0;
    95
    96    memset(&sndfile_info, 0, sizeof(SF_INFO));
    97
    98    // Try and open the virtual file.
    99    sndfile = sf_open_virtual(&vio, SFM_READ, &sndfile_info, &vio_data);
   100
   101    if (sndfile_info.channels == 0)
   102    {
   103      // No sound channels in file.
   104      goto EXIT_LABEL;
   105    }
   106    else if (sndfile_info.channels > 1024 * 1024)
   107    {
   108      // Too many channels to handle.
   109      goto EXIT_LABEL;
   110    }
   111
   112    // Just the right number of channels. Create some buffer space for reading.
   113    read_buffer = (float*)malloc(sizeof(float) * sndfile_info.channels);
   114    if (read_buffer == NULL)
   115    {
   116      abort();
   117    }
   118
   119    while (sf_readf_float(sndfile, read_buffer, 1))
   120    {
   121      // Do nothing with the data.
   122    }
   123
   124  EXIT_LABEL:
   125
   126    if (sndfile != NULL)
   127    {
   128      sf_close(sndfile);
   129    }
   130
   131    free(read_buffer);
   132
   133    return 0;
   134  }
